const customStyle=node('style');customStyle.id='lv-custom-style';D.head.append(customStyle);
$('styleMode').value=config.styleMode==='custom'?'custom':'theme';$('customCss').value=typeof config.customCss==='string'?config.customCss:'';
function scopedCss(css){const parser=node('style');parser.media='not all';parser.textContent=css;D.head.append(parser);try{const root=':is(#lv-dialog, #lv-selection, .lv-inline-audio, .lv-version-menu)';const compile=rules=>Array.from(rules,rule=>{if(rule.type===1){const selector=rule.selectorText.replace(/:root\b|:scope\b|:host\b/g,root);const body=rule.cssText.slice(rule.cssText.indexOf('{'));return `${root}:is(${selector}), ${root} :is(${selector}) ${body}`;}if(rule.type===4||rule.type===12)return rule.cssText.slice(0,rule.cssText.indexOf('{')+1)+compile(rule.cssRules)+'}';if(rule.type===7)return rule.cssText;return '';}).join('\n');return compile(parser.sheet.cssRules);}finally{parser.remove();}}
function applyStyle(){customStyle.textContent=config.styleMode==='custom'?scopedCss(config.customCss||''):'';}
on($('saveStyle'),'click',()=>{const previous={styleMode:config.styleMode,customCss:config.customCss};try{const css=$('customCss').value;scopedCss(css);config.styleMode=$('styleMode').value;config.customCss=css;if(!store()){Object.assign(config,previous);return;}applyStyle();status('外观已保存。');}catch(e){Object.assign(config,previous);status('CSS 无法应用：'+e.message);}});
on($('resetStyle'),'click',()=>{const previous={styleMode:config.styleMode,customCss:config.customCss};config.styleMode='theme';config.customCss='';if(!store()){Object.assign(config,previous);return;}$('styleMode').value='theme';$('customCss').value='';applyStyle();status('已恢复跟随酒馆。');});
applyStyle();
const syncBox=node('details');syncBox.dataset.id='sync';syncBox.innerHTML=`<summary>导入与导出</summary><label class="lv-check"><input data-id="includeKeys" type="checkbox">包含 API Key（文件中明文保存）</label><label>重复条目<select data-id="syncConflict"><option value="keep">保留本地版本</option><option value="replace">使用导入版本</option></select></label><div class="lv-row"><button type="button" data-id="exportBackup">导出同步文件</button><button type="button" data-id="importBackup">导入同步文件</button></div><input type="file" data-id="backupFile" accept="application/json,.json" hidden><p>包含录音、收藏状态、音色和已保存的接口。导入合并，不删除其他条目。</p>`;$('configPage').prepend(syncBox);
