async function saveFile(blob,name){if(W.PearAndroid&&W.pearSaveBlob)return W.pearSaveBlob(blob,name);const url=W.URL.createObjectURL(blob),a=node('a');a.href=url;a.download=name;D.body.append(a);a.click();a.remove();downloadUrls.add(url);later(()=>{W.URL.revokeObjectURL(url);downloadUrls.delete(url);},60000);}
for(const id of ['audio','historyAudio'])on($(id),'play',()=>{announceVoicePlayback();stopInline();for(const other of ['audio','historyAudio'])if(other!==id)$(other).pause();});
async function toBase64(bytes){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]);r.onerror=()=>reject(Error('无法读取音频。'));r.readAsDataURL(new W.Blob([bytes]));});}
function fromBase64(value){if(typeof value!=='string'||!value.length||value.length>70*1024*1024||value.length%4||!/^[A-Za-z0-9+/]*={0,2}$/.test(value))throw Error('同步文件中的音频无效。');return Uint8Array.from(atob(value),c=>c.charCodeAt(0)).buffer;}
async function exportBackup(){await profilesReady;const records=await historyList();if(records.reduce((n,r)=>n+(Number(r.size)||0),0)>100*1024*1024)throw Error('同步内容超过 100 MB，请先单独下载部分录音。');const profiles=structuredClone(apiProfiles);if(!$('includeKeys').checked)for(const kind of ['mini','sub'])for(const row of profiles[kind])delete row.key;const data={format:'lili-voice-backup',version:1,createdAt:Date.now(),config:structuredClone(config),profiles,records:[],songs:[]};let total=0;for(const [key,rows] of [['records',records]])for(const row of rows){const entry=await historyTx(['audio'],'readonly',tx=>{const r=tx.objectStore('audio').get(row.id);return ()=>r.result;});if(!entry?.bytes)throw Error('有音频缺失，未生成不完整的同步文件。');total+=entry.bytes.byteLength;if(total>100*1024*1024)throw Error('同步内容超过 100 MB。');data[key].push({...row,audio:await toBase64(entry.bytes)});}await saveFile(new W.Blob([JSON.stringify(data)],{type:'application/json'}),'梨梨配音室-'+new Date().toISOString().slice(0,10)+'.livoice.json');status(`已导出 ${records.length} 条录音。`);}
function validString(v,max=10000){return typeof v==='string'&&v.length<=max;}
function validateBackup(data){if(data?.format!=='lili-voice-backup'||data.version!==1)throw Error('不是支持的梨梨配音室同步文件。');if(!Array.isArray(data.records)||data.records.length>10000)throw Error('同步文件条目无效。');data.skippedSongs=Array.isArray(data.songs)?data.songs.length:0;delete data.songs;let total=0;const ids=new Set();for(const row of data.records){if(!row||!validString(row.id,200)||!row.id||row.id.startsWith('song-')||ids.has(row.id)||!Number.isFinite(row.createdAt)||Math.abs(row.createdAt)>8640000000000000||!validString(row.mime,100)||!row.mime.startsWith('audio/')||!validString(row.text,100000))throw Error('同步文件中的条目无效。');if(!['voiceName','voiceId','voiceGroup','language','model','host'].every(k=>validString(row[k],2048)))throw Error('录音信息无效。');ids.add(row.id);row.bytes=fromBase64(row.audio);delete row.audio;total+=row.bytes.byteLength;if(total>100*1024*1024)throw Error('同步内容超过 100 MB。');row.size=row.bytes.byteLength;if(typeof row.favorite==='boolean')row.favoriteSynced=false;}
for(const row of data.records){if(!row.mix)continue;if(row.mix.version!==1||!Array.isArray(row.mix.parts)||row.mix.parts.length<1||row.mix.parts.length>40||new Set(row.mix.parts).size!==row.mix.parts.length||row.mix.parts.some(id=>!ids.has(id)||id===row.id||data.records.find(r=>r.id===id)?.mix))throw Error('合成片段引用无效或缺失。');}const voices=data.config?.voices;if(!Array.isArray(voices)||voices.length>500||!voices.every(v=>v&&validString(v.id,200)&&v.id&&validString(v.name,500)&&validString(v.voiceId,500)&&Number.isFinite(v.speed)&&v.speed>=.5&&v.speed<=2&&Number.isFinite(v.volume)&&v.volume>0&&v.volume<=10&&Number.isInteger(v.pitch)&&v.pitch>=-12&&v.pitch<=12))throw Error('音色配置无效。');for(const kind of ['mini','sub']){const rows=data.profiles?.[kind];if(!Array.isArray(rows)||rows.length>500||!rows.every(p=>p&&validString(p.id,200)&&p.id&&validString(p.name,500)&&validString(p.model,500)&&(p.key===undefined||validString(p.key,20000))&&validString(kind==='mini'?p.host:p.url,2048)))throw Error('接口配置无效。');for(const p of rows){if(kind==='sub'&&((p.models!==undefined&&(!Array.isArray(p.models)||p.models.length>10000||!p.models.every(m=>validString(m,500))))||(p.prompt!==undefined&&!validString(p.prompt,20000)))||kind==='mini'&&(p.groupId!==undefined&&!validString(p.groupId,500)))throw Error('接口参数无效。');const url=new URL(kind==='mini'?p.host:p.url);if(!['http:','https:'].includes(url.protocol)||url.username||url.password)throw Error('导入的接口地址无效。');if(kind==='mini'&&!['api.minimax.cn','api.minimaxi.com','api.minimax.io'].includes(url.hostname))throw Error('MiniMax 接口地址无效。');}}
return data;}
async function importBackup(file){if(file.size>145*1024*1024)throw Error('同步文件过大，最大 145 MB。');const data=validateBackup(JSON.parse(await file.text()));await profilesReady;clearInlineCache();const replace=$('syncConflict').value==='replace',next=structuredClone(apiProfiles);for(const kind of ['mini','sub']){for(const p of data.profiles[kind]){const old=next[kind].find(x=>x.id===p.id);if(!old)next[kind].push(p);else if(replace){const key=p.key===undefined?old.key:p.key;Object.assign(old,p,{key});}else if(!old.key&&p.key)old.key=p.key;}const active=profileIds(kind).active;if(!next[active]&&next[kind].some(p=>p.id===data.profiles[active]))next[active]=data.profiles[active];}const nextConfig=structuredClone(config);for(const v of data.config.voices){const old=nextConfig.voices.find(x=>x.id===v.id);if(!old)nextConfig.voices.push(v);else if(replace)Object.assign(old,v);}await persistProfiles(next);W.localStorage.setItem(STORE,JSON.stringify(nextConfig));config=nextConfig;const existing=new Set((await historyList()).map(r=>r.id));let added=0;await historyTx(['records','audio'],'readwrite',tx=>{for(const [kind,rows] of [['records',data.records]])for(const entry of rows){if(existing.has(entry.id)&&!replace)continue;const {bytes,...row}=entry;tx.objectStore(kind).put(row);tx.objectStore('audio').put({id:row.id,bytes});existing.add(row.id);added++;}});renderVoices();renderProfiles();for(const kind of ['mini','sub']){const p=apiProfiles[kind].find(x=>x.id===apiProfiles[profileIds(kind).active]);if(p)fillApiProfile(kind,p);}await renderHistory();void loadInline();scheduleFavorites();status(`导入完成：合并 ${added} 条音频，音色与接口已合并。${data.skippedSongs?" 歌曲内容已跳过，插件只导入录音。":""}`);}
async function syncAction(fn){if(syncBusy)return;if(pending||batchBusy||mixBusy||translationPending||profilesBusy||$('test').disabled||$('fetchModels').disabled)return status('请先停止当前请求。');syncBusy=true;const controls=[...dialog.querySelectorAll('button,input,select,textarea')].filter(el=>!el.disabled);for(const el of controls)el.disabled=true;try{status('正在处理同步文件…');await fn();}catch(e){status('同步未完成：'+safe(e.message)+' 可重新导入，已合并条目不会重复。');}finally{syncBusy=false;for(const el of controls)el.disabled=false;}}
on($('exportBackup'),'click',()=>syncAction(exportBackup));on($('importBackup'),'click',()=> $('backupFile').click());on($('backupFile'),'change',()=>{const file=$('backupFile').files[0];$('backupFile').value='';if(file)syncAction(()=>importBackup(file));});

