async function patchFavorite(id,values){return historyTx(['records'],'readwrite',tx=>{const store=tx.objectStore('records'),get=store.get(id);get.onsuccess=()=>{if(get.result)store.put({...get.result,...values});};});}
async function sendFavorite(row,api){if(row.favorite){const blob=await historyBlob(row.id);await api.add({id:row.id,title:row.title||firstSentence(row.text),text:row.text,voiceName:row.voiceName,createdAt:row.createdAt,blob});}else await api.remove(row.id);await patchFavorite(row.id,{favoriteSynced:true});}
async function changeFavorite(id){return favoriteTask(async()=>{const row=(await historyList()).find(r=>r.id===id);if(!row)throw Error('这条录音已删除。');const bridge=playlistBridge();if(row.favorite&&bridge?.canRemove){await bridge.ready;if(!await bridge.canRemove(row.id))throw Error('这段语音已合成到工作台的大配音，请先拆开再取消收藏。');}row.favorite=!row.favorite;await patchFavorite(id,{favorite:row.favorite,favoriteSynced:false});let copied=false;try{const api=playlistBridge();if(api){await api.ready;await sendFavorite(row,api);copied=true;}}catch(e){voiceNotice('收藏已保存在配音室，歌单同步暂未完成：'+safe(e.message));await loadInline();return;}await loadInline();if(!$('historyPage').hidden)await renderHistory(false);voiceNotice(row.favorite?(copied?'已收藏到工作台 · 我的语音。':'已收藏到配音室，启用新版工作台后会同步到「我的语音」。'):'已取消收藏；其他歌单里的音频仍保留。');});}
function scheduleFavorites(){if(favoriteScheduled||dead||!playlistBridge())return;favoriteScheduled=true;later(()=>{favoriteScheduled=false;void favoriteTask(async()=>{const api=playlistBridge();if(!api)return;await api.ready;const rows=await historyList();let changed=false;for(const row of rows){if(typeof row.favorite!=='boolean'||row.favoriteSynced===true)continue;await sendFavorite(row,api);row.favoriteSynced=true;changed=true;}const ids=new Set(await api.ids());for(const row of rows){if(row.favoriteSynced!==true)continue;const favorite=ids.has(row.id);if(!!row.favorite!==favorite){await patchFavorite(row.id,{favorite});changed=true;}}if(changed){await loadInline();if(!$('historyPage').hidden)await renderHistory(false);}}).catch(e=>voiceNotice('语音歌单同步暂未完成：'+safe(e.message)));},120);}
on(W,'pear-workbench:voice-ready',scheduleFavorites);on(W,'lili-music-changed',scheduleFavorites);
