function getSelectionText(doc=D,floor=null){const input=doc.activeElement;if(input?.matches('textarea,input[type=text],input:not([type])')&&(floor||input.closest('.mes'))&&input.selectionEnd>input.selectionStart)return input.value.slice(input.selectionStart,input.selectionEnd).trim();const s=doc.getSelection();if(!s||s.isCollapsed||!s.rangeCount)return '';const el=n=>n?.nodeType===1?n:n?.parentElement;const a=el(s.anchorNode),b=el(s.focusNode);if(a?.closest('#lv-dialog')||b?.closest('#lv-dialog'))return '';const ma=a?.closest('.mes'),mb=b?.closest('.mes');if(!floor&&ma&&mb&&ma!==mb)return '';const fragment=s.getRangeAt(0).cloneContents();if(fragment.querySelector('.lv-inline-audio')){fragment.querySelectorAll('.lv-inline-audio').forEach(e=>e.remove());return fragment.textContent.trim();}return s.toString().trim();}
function hideSelectionButton(){if(selectionButton.hasAttribute('popover')&&selectionButton.matches(':popover-open'))selectionButton.hidePopover();selectionButton.hidden=true;}
function activeSelectionDocument(){let doc=D,floor=null;for(let i=0;i<12;i++){const frame=doc.activeElement;if(frame?.tagName!=='IFRAME')break;try{const inner=frame.contentDocument;if(!inner)break;floor=floor||frame.closest('.mes');doc=inner;}catch{break;}}return {doc,floor};}
function positionSelectionButton(doc){
 const viewport=W.visualViewport,left=viewport?.offsetLeft||0,top=viewport?.offsetTop||0,width=viewport?.width||W.innerWidth,height=viewport?.height||W.innerHeight;
 let x=left+width-160,y=top+height-210;
 try{const sel=doc.getSelection();let rect=sel?.rangeCount?sel.getRangeAt(sel.rangeCount-1).getBoundingClientRect():null;if(rect&&(rect.width||rect.height)){x=rect.left;y=rect.bottom;let selectionTop=rect.top;let win=doc.defaultView;while(win&&win!==W){const frame=win.frameElement;if(!frame)break;const r=frame.getBoundingClientRect(),sx=r.width/(frame.offsetWidth||r.width),sy=r.height/(frame.offsetHeight||r.height);x=r.left+x*sx;y=r.top+y*sy;selectionTop=r.top+selectionTop*sy;win=frame.ownerDocument.defaultView;}y+=40;const buttonHeight=selectionButton.offsetHeight||44;if(y+buttonHeight>top+height-100)y=selectionTop-buttonHeight-110;}}catch{}
 const bw=selectionButton.offsetWidth||150,bh=selectionButton.offsetHeight||44;
 selectionButton.style.left=Math.max(left+8,Math.min(x,left+width-bw-8))+'px';selectionButton.style.top=Math.max(top+8,Math.min(y,top+height-bh-12))+'px';
}
function excerptVoiceVisible(){return [...D.querySelectorAll('#be-float-bar .lv-be-button, #be-hl-bar .lv-be-button')].some(button=>{const bar=button.closest('#be-float-bar,#be-hl-bar');if(!bar?.classList.contains('show'))return false;for(let el=button;el;el=el.parentElement){const css=W.getComputedStyle(el);if(el.hidden||css.display==='none'||css.visibility==='hidden'||Number(css.opacity)===0)return false;}const r=button.getBoundingClientRect();return r.width>0&&r.height>0&&r.bottom>0&&r.right>0&&r.top<W.innerHeight&&r.left<W.innerWidth;});}
function selected(doc,floor){if(dialog.open){hideSelectionButton();return;}if(!doc){const active=activeSelectionDocument();doc=active.doc;floor=active.floor;}const t=getSelectionText(doc,floor);if(capturedSelection&&!t)return;lastSelection=t;selectedSource=t?captureSource(doc,floor):null;if(!t||excerptVoiceVisible()){hideSelectionButton();return;}selectionButton.hidden=false;if(selectionButton.hasAttribute('popover')&&!selectionButton.matches(':popover-open')){try{selectionButton.showPopover();}catch{}}positionSelectionButton(doc);}

const frameEntries=new Map();
function scanFrames(root=D,floor=null){
 for(const [frame,entry] of frameEntries)if(!frame.isConnected){entry.dispose();frameEntries.delete(frame);}
 for(const frame of root.querySelectorAll('iframe')){
  const message=floor||frame.closest('.mes');if(!message)continue;
  if(!frameEntries.has(frame)){
   let removeDoc=()=>{};
   const bind=()=>{removeDoc();try{const doc=frame.contentDocument;if(!doc)return;const watch=new W.MutationObserver(records=>{if(records.some(r=>!ownUiMutation(r)))scheduleInline();});watch.observe(doc.body||doc,{childList:true,subtree:true,characterData:true});scheduleInline();const select=()=>later(()=>selected(doc,message),80);doc.addEventListener('selectionchange',select);doc.addEventListener('pointerup',select);removeDoc=()=>{watch.disconnect();doc.removeEventListener('selectionchange',select);doc.removeEventListener('pointerup',select);};scanFrames(doc,message);}catch{}};
   const entry={dispose:()=>{removeDoc();frame.removeEventListener('load',bind);}};frameEntries.set(frame,entry);frame.addEventListener('load',bind);bind();
  }
 }
}
function highlighted(){if(!lastHighlight?.message?.isConnected)return '';return [...lastHighlight.message.querySelectorAll('.be-highlight[data-be-id]')].filter(s=>s.getAttribute('data-be-id')===lastHighlight.id).map(s=>s.textContent).join('').trim();}
