function drawBatch(){const box=$('batchLines');box.replaceChildren();batchDraft.forEach((row,i)=>{const card=node('div',null,'lv-script-line'),voice=node('select'),text=node('textarea'),state=node('p');voice.setAttribute('aria-label','第 '+(i+1)+' 段音色');for(const v of config.voices){const o=node('option',v.name);o.value=v.id;voice.append(o);}voice.value=config.voices.some(v=>v.id===row.voice)?row.voice:config.selected;row.voice=voice.value;text.value=row.text;text.rows=3;text.maxLength=9999;text.setAttribute('aria-label','第 '+(i+1)+' 段台词');voice.onchange=()=>{row.voice=voice.value;saveBatchDraft();};text.oninput=()=>{row.text=text.value;saveBatchDraft();};state.textContent=row.recordId?'已有生成片段，台词或音色改变后会重新生成。':'尚未生成';const actions=node('div',null,'lv-row');for(const [label,delta] of [['↑',-1],['↓',1]]){const b=node('button',label);b.type='button';b.setAttribute('aria-label','移动台词 '+(i+1)+' '+label);b.disabled=batchBusy||i+delta<0||i+delta>=batchDraft.length;b.onclick=()=>{[batchDraft[i],batchDraft[i+delta]]=[batchDraft[i+delta],batchDraft[i]];saveBatchDraft();drawBatch();};actions.append(b);}const del=node('button','删除台词');del.type='button';del.disabled=batchBusy||batchDraft.length===1;del.onclick=()=>{batchDraft.splice(i,1);saveBatchDraft();drawBatch();};actions.append(del);card.append(node('b','第 '+(i+1)+' 段'),voice,text,actions,state);box.append(card);});}
