async function renderVoiceMix(blobs,options,check=()=>{},progress=()=>{}){const Offline=W.OfflineAudioContext||W.webkitOfflineAudioContext;if(!Offline)throw Error('浏览器不支持本地合成。');if(blobs.reduce((n,b)=>n+b.size,options.bgm?.size||0)>100*1024*1024)throw Error('单次音频总量最大 100 MB。');const decoder=new Offline(2,1,24000),buffers=[];let duration=0;for(let i=0;i<blobs.length;i++){check();progress('读取片段 '+(i+1)+' / '+blobs.length);const buffer=await decoder.decodeAudioData(await blobs[i].arrayBuffer());check();duration+=buffer.duration+(i?options.gap:0);if(!Number.isFinite(duration)||duration>600)throw Error('大配音最长 10 分钟，请分段合成。');buffers.push(buffer);}if(duration<=0)throw Error('没有有效音频。');const background=options.bgm?await decoder.decodeAudioData(await options.bgm.arrayBuffer()):null;check();const offline=new Offline(2,Math.ceil(duration*24000),24000);let offset=0;for(const buffer of buffers){const source=offline.createBufferSource();source.buffer=buffer;source.connect(offline.destination);source.start(offset);offset+=buffer.duration+options.gap;}if(background){const source=offline.createBufferSource(),gain=offline.createGain(),fade=Math.min(.5,duration/4);source.buffer=background;source.loop=true;gain.gain.setValueAtTime(0,0);gain.gain.linearRampToValueAtTime(options.volume,fade);gain.gain.setValueAtTime(options.volume,duration-fade);gain.gain.linearRampToValueAtTime(0,duration);source.connect(gain);gain.connect(offline.destination);source.start(0);source.stop(duration);}progress('正在合成声音…');const audio=await offline.startRendering();check();const left=audio.getChannelData(0),right=audio.getChannelData(1);let peak=1;for(let i=0;i<audio.length;i++)peak=Math.max(peak,Math.abs(left[i]),Math.abs(right[i]));const bytes=new ArrayBuffer(44+audio.length*4),view=new DataView(bytes),word=(at,text)=>[...text].forEach((c,i)=>view.setUint8(at+i,c.charCodeAt(0)));word(0,'RIFF');view.setUint32(4,bytes.byteLength-8,true);word(8,'WAVE');word(12,'fmt ');view.setUint32(16,16,true);view.setUint16(20,1,true);view.setUint16(22,2,true);view.setUint32(24,24000,true);view.setUint32(28,96000,true);view.setUint16(32,4,true);view.setUint16(34,16,true);word(36,'data');view.setUint32(40,bytes.byteLength-44,true);for(let i=0;i<audio.length;i++){if(!(i%131072)){check();await new Promise(resolve=>W.setTimeout(resolve,0));}view.setInt16(44+i*4,Math.round(Math.max(-1,Math.min(1,left[i]/peak))*32767),true);view.setInt16(46+i*4,Math.round(Math.max(-1,Math.min(1,right[i]/peak))*32767),true);}return new W.Blob([bytes],{type:'audio/wav'});}
async function synthesizeVoice(c,v,text,key,signal){validatePerformance(text,c.model,v.emotion);const body={model:c.model,text,stream:false,output_format:'hex',language_boost:c.language,voice_setting:{voice_id:v.voiceId,speed:Number(v.speed),vol:Number(v.volume),pitch:Number(v.pitch),...(v.emotion?{emotion:v.emotion}:{})},audio_setting:{sample_rate:32000,bitrate:128000,format:'mp3',channel:1}};const response=await raw(c,'speak',body,key,signal);if(response.ok&&response.type.startsWith('audio/'))return new W.Blob([response.bytes],{type:response.type.split(';')[0]});const j=checked(response),hex=String(j.data?.audio||'').replace(/^0x/,'').replace(/\s/g,'');if(!hex||hex.length%2||!/^[0-9a-f]+$/i.test(hex))throw Error('接口没有返回有效音频。');const bytes=new Uint8Array(hex.length/2);for(let i=0;i<bytes.length;i++)bytes[i]=parseInt(hex.slice(i*2,i*2+2),16);return new W.Blob([bytes],{type:'audio/mpeg'});}
